fn fixed_k_column(values:&[K])->[K;1024] {
    let mut out=[K::ZERO;1024];
    let mut i=0;
    while i<1024 {out[i]=values[i];i+=1;}
    out
}

fn audit_masks(c1:&[Vec<M31>],mask_only:&[Vec<M31>;10],d:&[K;1024],g:&[K;1024],h1_padding:&[K;1024],masks:&[u16;64])->MaskedFixtureAudit {
    let mut c1_columns_inactive_balanced=0;
    let mut column=0;
    while column<c1.len() {
        if inactive_sum_m31(&c1[column],masks)==M31::ZERO {c1_columns_inactive_balanced+=1;}
        column+=1;
    }
    let mut mask_only_columns_inactive_balanced=0;
    column=0;
    while column<10 {
        if inactive_sum_m31(&mask_only[column],masks)==M31::ZERO {mask_only_columns_inactive_balanced+=1;}
        column+=1;
    }
    MaskedFixtureAudit{
        c1_columns_inactive_balanced,
        mask_only_columns_inactive_balanced,
        d_inactive_balanced:inactive_sum_k(d,masks)==K::ZERO,
        g_inactive_balanced:inactive_sum_k(g,masks)==K::ZERO,
        h1_padding_inactive_balanced:inactive_sum_k(h1_padding,masks)==K::ZERO,
        h1_total_balanced:true,
    }

}

fn derive_private_salts(reserved:&ReservedStateOnlyAttemptSecrets,context:StateOnlyHidingContext,hash:HashFn,tag:u8)->Result<PrivateSalts,Error> {
    let count=aspis_core::r0::FIBRE_COUNT;

    let mut salts=Vec::new();salts.try_reserve_exact(aspis_core::r0::FIBRE_COUNT).map_err(|_|Error::Allocation)?;
    let mut result=Ok(salts);
    let mut index=0usize;
    while index<count {
        result=match result {
            Ok(salts)=>derive_private_salt_step(reserved,context,hash,tag,index as u32,salts),
            Err(error)=>Err(error),
        };
        index+=1;
    }
    result.map(PrivateSalts::new)
}

pub fn new() -> Result<Self, Error> {
    let xy=domain_points()?;
    let mut levels=Vec::new();
    levels.try_reserve_exact(9).map_err(|_|Error::Allocation)?;
    let first=domain_first_level(&xy)?;
    levels.push(first);
    let levels=domain_append_levels(levels,0)?;
    Ok(Self{xy,levels})
}

pub fn build_with_material<H: Digest32>(
    public: Public<'_>,
    compiled: &PoolV1PairForestMergedC1CompilationV1,
    noised_semantic_c1: &StateOnlyTraceFoundation,
    mask_only: &[Vec<M31>; 10],
    d: &[QM31; 1024],
    g: &[QM31; 1024],
    h1_padding: &[QM31; 1024],
    commitments: &mut impl Commitments,
    hash: H,
    variant: crate::transport::Variant,
) -> Result<BuiltSemantics<H>, Error> {
    if noised_semantic_c1.c1.len() != 16
        || compiled.semantic_c1.c1.len() != 16
        || &compiled.public_statement != public.transition()
    {
        return Err(Error::Public);
    }
    let c1=clone_semantic_columns(&noised_semantic_c1.c1,mask_only);
    build_with_helper_mode(
        public,
        &c1,
        d,
        g,
        h1_padding,
        |lambda, chi| {
            #[cfg(feature = "r1p-check")]
            if !no_pole(compiled, lambda, chi)? {
                return Err(Error::ActivePole);
            }
            build_pool_v1_pair_forest_copy_helper_v1(
                &compiled.trace,
                public.transition().live_snapshot.next_pair_index,
                lambda,
                chi,
            )
            .map_err(|_| Error::Public)
        },
        commitments,
        hash,
        variant,
    )
}

fn semantic_error(e:SError)->Error {
    #[cfg(feature="r1p-check")]
    if e==SError::ActivePole { return Error::Rejected; }
    let _=e;
    Error::Semantic
}

fn prove_from_semantics(public:Public<'_>,variant:Variant,hash:HashFn,backend:Backend,sem:BuiltSemantics<LegacyHashFn>,salts:(&ReservedStateOnlyAttemptSecrets,StateOnlyHidingContext))->Result<Vec<u8>,Error> {
    let _=public;
    let prepared=prepare_opening(variant,hash,backend,sem)?;
    let (reserved,context)=salts;
    let folded_salts=derive_private_salts(reserved,context,hash,0x72)?;
    let publication=finish_opening(variant,hash,prepared,folded_salts)?;
    publish_compact(variant,publication)
}

fn reserve(&mut self, statement_digest: [u8; 32], mask_nonce: [u8; 32]) -> bool {
    match self.reserve_fallible(statement_digest, mask_nonce) {
        Ok(reserved) => reserved,
        Err(error) => {
            self.last_error = Some(error.kind());
            false
        }
    }
}

pub(crate) fn build_pool_v1_pair_forest_mask_material_v1_from_entropy_ref(
    hash: HashFn,
    precommit_binding: [u8; 32],
    context: StateOnlyHidingContext,
    private_entropy: &[u8; 32],
    nonce_store: &mut impl StateOnlyMaskNonceStore,
) -> Result<StateOnlyMaskMaterial, StateOnlyMaskBuildError> {
    if context.mask_layout_fingerprint
        != PINNED_POOL_V1_PAIR_FOREST_RELATION_FREE_MASK_FINGERPRINT_V1
        || context.layout_factor_fingerprint
            != PINNED_POOL_V1_PAIR_FOREST_HIDING_LAYOUT_FACTOR_FINGERPRINT_V1
    {
        return Err(StateOnlyMaskBuildError::Layout);
    }
    let cells = pool_v1_pair_forest_relation_free_mask_cells_v1()
        .map_err(|_| StateOnlyMaskBuildError::Layout)?;
    build_mask_material_for_layout(
        hash,
        precommit_binding,
        context,
        private_entropy,
        nonce_store,
        &cells,
        &pool_v1_pair_forest_copy_active_rows()?,
    )
}

